using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using LWS.TruckSports.Editor;
namespace LWS.TruckSnake.Editor {
 public static class SnakeSceneryAuthoring {
  public static void Install(SnakeMatch m){var root=new GameObject("Composed five-region owned environment").transform;
   string buildings="Assets/JC_LP_MegaCity/Prefabs/Buildings/";
   for(int i=0;i<12;i++){float x=830+i%3*180,z=(i/3%2==0?-1:1)*(140+i/6*150);Model(m,root,"Industrial warehouse "+i,buildings+(i%3==0?"SM_Buildings_Factory_01":"SM_Buildings_Warehouse_01")+".prefab",new Vector3(x,0,z),new Vector3(75,35,60),true);}
   for(int i=0;i<64;i++){float x=790+i%8*65,z=(i/8%2==0?-1:1)*(55+i/16*35);var model=Model(m,root,"Physical cargo container "+i,"Assets/ShipContainerPack/URP/Prefabs/ShipContainerRed_URP.prefab",new Vector3(x,0,z),new Vector3(16,4,4),false);var shape=model.gameObject.AddComponent<BoxCollider>();shape.center=Vector3.up*2;shape.size=new Vector3(16,4,4);}
   var steel=SportsEventAuthoring.Mat("TruckSnake","Cargo gantry safety red",new Color(.75f,.13f,.06f),.4f);var crane=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/TruckBungeeDemolition/Models/Lattice Crane.asset");if(crane==null)throw new InvalidOperationException("Existing modeled lattice crane required.");
   for(int i=0;i<3;i++){var g=new GameObject("Working cargo-yard gantry landmark "+i);g.transform.SetParent(root,false);g.transform.position=new Vector3(875+i*150,m.world.Height(new Vector3(875+i*150,0,280)),280);g.AddComponent<MeshFilter>().sharedMesh=crane;g.AddComponent<MeshRenderer>().sharedMaterial=steel;var size=crane.bounds.size;g.transform.localScale=new Vector3(25/size.x,42/size.y,25/size.z);g.transform.position-=Vector3.Scale(new Vector3(crane.bounds.center.x,crane.bounds.min.y,crane.bounds.center.z),g.transform.localScale);g.AddComponent<MeshCollider>().sharedMesh=crane;}
   for(int i=0;i<16;i++){float x=-1150+i%4*125,z=-350+i/4*170;Model(m,root,"Countryside home and farm "+i,buildings+(i%3==0?"SM_Buildings_House_06_V1":i%3==1?"SM_Buildings_House_04_V1":"SM_Buildings_House_02_V1")+".prefab",new Vector3(x,0,z),new Vector3(27,20,28),true);}
   var random=new System.Random(712991);for(int i=0;i<64;i++){var p=new Vector3(-1450+(float)random.NextDouble()*2900,0,-1150+(float)random.NextDouble()*2300);if(Mathf.Abs(p.x)<500&&Mathf.Abs(p.z)<500||p.x>650&&p.z<500||p.z<-500&&Mathf.Abs(p.x)<650)continue;bool near=m.world.graph.edges.Any(edge=>edge.samples.Any(s=>Vector3.ProjectOnPlane(s.position-p,Vector3.up).sqrMagnitude<45*45));if(near)continue;Model(m,root,"Terrain-grounded country rock "+i,"Assets/PinwheelStudio/Vista/Personal/Samples/Prefabs/VistaSample_DesertRock.prefab",p,new Vector3(8+i%4*2,5+i%3*2,9+i%4),true);}
   HighwaySupports(m,root);RegionSigns(m,root);Border(m,root);
  }
  static Transform Model(SnakeMatch m,Transform parent,string name,string path,Vector3 point,Vector3 size,bool collision){var holder=new GameObject(name).transform;holder.SetParent(parent,false);point.y=m.world.Height(point)+.05f;holder.position=point;LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder,path,size,0,false,"TruckSnake");if(collision)foreach(var filter in holder.GetComponentsInChildren<MeshFilter>())if(filter.sharedMesh!=null&&filter.GetComponent<Collider>()==null)filter.gameObject.AddComponent<MeshCollider>().sharedMesh=filter.sharedMesh;return holder;}
  static void RegionSigns(SnakeMatch m,Transform parent){var locations=new[]{new Vector3(10,0,355),new Vector3(690,0,30),new Vector3(20,0,595),new Vector3(-690,0,30),new Vector3(20,0,-595)};for(int i=0;i<locations.Length;i++){var p=locations[i];p.y=m.world.Height(p)+5;var text=SportsEventAuthoring.Label("Readable region landmark",m.world.regions[i].ToUpperInvariant(),p,.7f,new Color(1,.82f,.1f));text.transform.SetParent(parent,true);text.transform.rotation=Quaternion.Euler(0,i==1?90:i==3?-90:0,0);}}
  static void HighwaySupports(SnakeMatch m,Transform root){
   // Original modeled, tapered concrete piers under actual elevated spans.
   // They have a visible fluted shaft and bearing cap, rather than a box tower.
   string path="Assets/TruckSnake/Meshes/Fluted highway pier.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){var vertices=new System.Collections.Generic.List<Vector3>();var triangles=new System.Collections.Generic.List<int>();float[] y={0,.06f,.12f,.86f,.92f,1};float[] radius={.8f,.9f,.62f,.48f,.9f,1};for(int row=0;row<y.Length;row++)for(int i=0;i<16;i++){float a=i*Mathf.PI/8;vertices.Add(new Vector3(Mathf.Cos(a)*radius[row],y[row],Mathf.Sin(a)*radius[row]));if(row>0){int a0=(row-1)*16+i,b0=(row-1)*16+(i+1)%16,a1=row*16+i,b1=row*16+(i+1)%16;triangles.AddRange(new[]{a0,a1,b0,b0,a1,b1});}}mesh=new Mesh{name="Original fluted concrete bridge bearing pier"};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);}
   var concrete=SportsEventAuthoring.Mat("TruckSnake","Weathered bridge concrete",new Color(.51f,.54f,.56f),.12f);for(int side=-1;side<=1;side+=2)for(int i=0;i<10;i++){float x=-1000+i*220,z=side<0?410:990;var p=new Vector3(x,0,z);float ground=m.world.Height(p);var pier=new GameObject("Visible elevated-highway support "+side+" "+i);pier.transform.SetParent(root,false);pier.transform.position=new Vector3(x,ground,z);pier.transform.localScale=new Vector3(2.5f,21.8f,2.5f);pier.AddComponent<MeshFilter>().sharedMesh=mesh;pier.AddComponent<MeshRenderer>().sharedMaterial=concrete;pier.AddComponent<MeshCollider>().sharedMesh=mesh;}
  }
  static void Border(SnakeMatch m,Transform root){var material=SportsEventAuthoring.Mat("TruckSnake","Playable world perimeter safety blue",new Color(.08f,.32f,.5f),.4f);var physics=SportsEventAuthoring.Contact("TruckSnake","World perimeter contact",.2f,.04f);for(int axis=0;axis<2;axis++)for(int side=-1;side<=1;side+=2)for(int i=0;i<30;i++){var p=axis==0?new Vector3(side*1470,0,-1160+i*80):new Vector3(-1460+i*100,0,side*1170);p.y=m.world.Height(p)+1.1f;var fence=new GameObject("Visible continuous perimeter guardrail").transform;fence.SetParent(root,false);fence.position=p;fence.rotation=Quaternion.Euler(0,axis==0?90:0,0);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(fence,"Assets/JC_LP_MegaCity/Prefabs/FloorProps/SM_FloorProps_Fence_01.prefab",new Vector3(axis==0?80:100,2.2f,.4f),-1.1f,true,"TruckSnake");var shape=fence.gameObject.AddComponent<BoxCollider>();shape.center=Vector3.zero;shape.size=new Vector3(axis==0?80:100,2.2f,.4f);shape.sharedMaterial=physics;}}
 }
}
